from collections import Counter,deque
def comps(g,c):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==c and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True;s=[]
                while q:
                    a,b=q.popleft(); s.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==c and not seen[x][y]:
                            seen[x][y]=True;q.append((x,y))
                out.append(s)
    return out
